def solve ():
# The problem asks for the minimum number of perfect squares 
# (excluding 49 itself) that sum to 49.
# Perfect squares smaller than 49 are: 1, 4, 9, 16, 25, 36.
    squares =[1 ,4 ,9 ,16 ,25 ,36 ]
    target =49 

    # Use Breadth-First Search to find the shortest path (minimum terms)
    # queue stores (current_sum, number_of_terms)
    queue =[(0 ,0 )]
    visited ={0 }

    while queue :
        current_sum ,count =queue .pop (0 )

        if current_sum ==target :
            return count 

        for s in squares :
            next_sum =current_sum +s 
            if next_sum <=target and next_sum not in visited :
                visited .add (next_sum )
                queue .append ((next_sum ,count +1 ))

